<section class="heading"><span class="eyebrow">Последний шаг</span><h1>Оформление заказа</h1><p class="muted">Учебный заказ, без реальной оплаты и отправки.</p></section>
<?php if (!$summary['items']): ?><section class="empty"><h2>Корзина пуста</h2><a href="/catalog">Сначала выберите товары</a></section><?php else: ?>
<div class="checkout-grid"><section class="panel"><h2>Контакт и доставка</h2>
<?php if ($errors): ?><div class="error" role="alert"><strong>Исправьте данные формы</strong><ul><?php foreach ($errors as $message): ?><li><?= e($message) ?></li><?php endforeach ?></ul></div><?php endif ?>
<form method="post" action="/checkout" novalidate><input type="hidden" name="csrf" value="<?= e($csrf) ?>">
<?php foreach (['name' => 'Имя получателя', 'email' => 'Email', 'address' => 'Адрес для курьера'] as $field => $label): ?><label for="<?= e($field) ?>"><?= e($label) ?></label><input id="<?= e($field) ?>" name="<?= e($field) ?>" type="<?= $field === 'email' ? 'email' : 'text' ?>" value="<?= e($values[$field]) ?>" maxlength="<?= $field === 'name' ? 100 : ($field === 'email' ? 254 : 200) ?>" <?= isset($errors[$field]) ? 'aria-invalid="true" aria-describedby="error-' . e($field) . '"' : '' ?>><?php if (isset($errors[$field])): ?><small class="field-error" id="error-<?= e($field) ?>"><?= e($errors[$field]) ?></small><?php endif ?><?php endforeach ?>
<label for="delivery">Способ доставки</label><select id="delivery" name="delivery" <?= isset($errors['delivery']) ? 'aria-invalid="true" aria-describedby="error-delivery"' : '' ?>><option value="">Выберите доставку</option><?php foreach ($methods as $method): ?><option value="<?= e($method['id']) ?>" <?= $values['delivery'] === $method['id'] ? 'selected' : '' ?>><?= e($method['title']) ?> · <?= money($method['price_cents']) ?></option><?php endforeach ?></select>
<?php if (isset($errors['delivery'])): ?><small class="field-error" id="error-delivery"><?= e($errors['delivery']) ?></small><?php endif ?>
<p class="muted">Самовывоз: пункт выдачи учебного магазина. Адрес при самовывозе не требуется. Доставка прибавляется к сумме товаров.</p><button>Подтвердить заказ</button></form></section>
<aside class="panel"><h2>Ваш заказ</h2><?php foreach ($summary['items'] as $line): ?><p><?= e($line['product']->name) ?> × <?= $line['quantity'] ?> <strong><?= money($line['subtotal']) ?></strong></p><?php endforeach ?><p class="price">Товары: <?= money($summary['total']) ?></p><p class="muted">Стоимость выбранной доставки будет добавлена при сохранении заказа.</p><a href="/cart">Изменить корзину</a></aside></div><?php endif ?>
